head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > useCtrlKey]<br/>Ctrl 키와 마우스 클릭을 사용하여 복수의 Cell 선택이 가능하게 설정합니다.",
    "validation" : [
        "true(기본값) 설정 시 Ctrl 키를 누른 상태로 Cell 을 클릭하면 기존 선택 상태가 유지된 채 클릭된 Cell 이 선택됩니다.",
        "false 설정 시 Ctrl 키를 누른 상태로 Cell 을 클릭해도 기존 선택이 해제되고 클릭된 Cell 만 선택됩니다.",
        "focusMode='none' 이면 Cell 선택이 동작하지 않으므로 useCtrlKey 속성이 적용되지 않습니다.",
        "useCtrlKey 속성은 마우스로 클릭했을 경우 적용되며 키보드를 사용한 선택 처리에는 적용되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - con_focusMode      : cell(기본) / none  (정적 select1, @spec1 검증용. useCtrlKey 동작에는 focusMode!=none 필요)
//  - con_useCtrlKey     : 공통 gdl_boolean → getText() ('' 미설정=속성제외, 기본 true / 'true' / 'false')
//  - con 값이 '' 이면 해당 속성 자체를 추가하지 않음(기본값 true 동작)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let vFocusMode   = con_focusMode.getValue();
    let vUseCtrlKey  = con_useCtrlKey.getText();

    // focusMode : 콤보 값 그대로 적용 (기본 cell)
    let properties = {
        focusMode : vFocusMode
    };

    // useCtrlKey : 미설정('') 이면 속성 자체를 추가하지 않음(기본 true)
    if (vUseCtrlKey === 'true') {
        properties.useCtrlKey = true;
    } else if (vUseCtrlKey === 'false') {
        properties.useCtrlKey = false;
    }

    let cList = $c.gcm.createCList(properties);

    let lblDesc = 'GridView focusMode=' + vFocusMode
        + ', useCtrlKey=' + (vUseCtrlKey === '' ? '(미설정=기본 true)' : vUseCtrlKey)
        + ' / Cell 클릭 후 Ctrl+클릭 으로 복수 선택 → [선택 범위 확인] 버튼으로 확인';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // 복수 선택 확인용 dataList 생성 (col1~col4, 6행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // target 생성 (4컬럼 Body 그리드)
    await scwin.createGridView(cList);
}



// 복수 선택 확인용 데이터 (6행)
scwin.fillData = function () {
    let rows = [
        { col1: "A1", col2: "B1", col3: "C1", col4: "D1" },
        { col1: "A2", col2: "B2", col3: "C2", col4: "D2" },
        { col1: "A3", col2: "B3", col3: "C3", col4: "D3" },
        { col1: "A4", col2: "B4", col3: "C4", col4: "D4" },
        { col1: "A5", col2: "B5", col3: "C5", col4: "D5" },
        { col1: "A6", col2: "B6", col3: "C6", col4: "D6" },
    ];
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성
scwin.createGridView = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:520px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="useCtrlKey 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 선택 범위 확인 :
//  - 사용자가 Cell 을 클릭한 뒤 다른 Cell 을 Ctrl+클릭하여 복수 선택한 상태에서 호출.
//  - getAllFocusedIndex() 로 현재 선택(포커스)된 Cell 의 {row, col} 목록과 개수를 출력.
//  - 실제 화면 선택 여부는 focusedTd CSS 클래스가 적용된 <td> 개수로 확인.
//  - useCtrlKey=true(또는 미설정) : 기존 선택 유지 + 추가(복수) / false : 마지막 클릭 Cell 1개만.
//  - focusMode='none' : Cell 선택이 동작하지 않으므로 화면 선택(focusedTd) 0개.
scwin.btn_checkSelectedRange_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[옵션] focusMode=" + target1.options.focusMode
        + " / useCtrlKey=" + target1.options.useCtrlKey);

    // 내부 포커스 인덱스 목록
    let focused = target1.getAllFocusedIndex();
    bottom.setReturnValue("getAllFocusedIndex : " + JSON.stringify(focused));

    // 화면에 실제 선택 표시(focusedTd)된 Cell 개수
    let focusedTds = document.querySelectorAll("td[id*='mf_target1_cell_'].focusedTd");
    bottom.setReturnValue("화면 선택(focusedTd) Cell 개수 : " + focusedTds.length);
}
